import { promises as fs } from 'fs';
import { join, dirname } from 'path';

/**
 * Recursively copies a file or directory from source to destination.
 * @param src - Source file or directory path
 * @param dest - Destination file or directory path
 * @returns Promise that resolves when copy is complete
 */
async function copyRecursive(src: string, dest: string): Promise<void> {
  // Get the stats (metadata) of the source path to determine if it's a file or directory
  const stats = await fs.stat(src);

  // If the source is a directory, create the destination directory if it doesn't exist
  if (stats.isDirectory()) {
    // Ensure the destination directory exists, creating it if necessary
    await fs.mkdir(dest, { recursive: true });

    // Read all entries (files and subdirectories) from the source directory
    const entries = await fs.readdir(src, { withFileTypes: true });

    // Iterate through each entry in the source directory
    for (const entry of entries) {
      // Construct the full source path for the current entry
      const srcPath = join(src, entry.name);

      // Construct the full destination path for the current entry
      const destPath = join(dest, entry.name);

      // Recursively call copyRecursive to copy the current entry
      await copyRecursive(srcPath, destPath);
    }
  } else {
    // If the source is a file, ensure the parent directory of the destination exists
    await fs.mkdir(dirname(dest), { recursive: true });

    // Copy the file from source to destination
    await fs.copyFile(src, dest);
  }
}
